// --- help texts (classes.cpp) ---
export const wormdes = "These huge monsters normally live below the sand, but your movements have disturbed them. They are too big to be slain with your weapons, but you can defeat them by making them unable to move. This also produces some Spice. They move two times slower than you.";
export const cocytushelp = "This frozen lake is a hellish version of the Icy Land. Now, your body heat melts the floor, not the walls.";
export const tentdes = "The tentacles of Cthulhu are like sandworms, but longer. They also withdraw one cell at a time, instead of exploding instantly.";
export const ivydes = "A huge plant growing in the Jungle. Each Ivy has many branches, and one branch grows per each of your moves. Branches grow in a clockwise order. The root itself is vulnerable.";
export const slimehelp = "The Alchemists produce magical potions from pools of blue and red slime. You can go through these pools, but you cannot move from a blue pool to a red pool, or vice versa. Pools containing items count as colorless, and they change color to the PC's previous color when the item is picked up. Slime beasts also have to keep to their own color, but when they are killed, they explode, destroying items and changing the color of the slime and slime beasts around them.";
export const gdemonhelp = "These creatures are slow, but very powerful... more powerful than you. You need some more experience in demon fighting before you will be able to defeat them. Even then, you will be able to slay this one, but more powerful demons will come...\n\nEach 10 lesser demons you kill, you become powerful enough to kill all the greater demons on the screen, effectively turning them into lesser demons.";
export const ldemonhelp = "These creatures are slow, but they often appear in large numbers.";
export const trollhelp = "A big monster from the Living Caves. A dead Troll will be reunited with the rocks, causing some walls to grow around its body.";
export const trollhelpX = "There are several species of trolls living in the hyperbolic world. Some of them leave this wall behind them when they die.";
export const camelothelp = "The Knights of the Round Table are the greatest warriors of these lands. They are not very inventive with names though, as they call each of their castles Camelot. You are probably worthy of joining them, but they will surely give you some quest to prove yourself...\n\nEach castle contains a single treasure, the Holy Grail, in the center. The radius of the Round Table is usually 28, but after you find a Holy Grail successfully, each new castle (and each Round Table) you find will be bigger.";
export const templehelp = "The temple of Cthulhu consists of many concentric circles of columns. You will surely encounter many Cultists there, who believe that a pilgrimage to the inner circles will bring them closer to Cthulhu himself, and Grimoires which surely contain many interesting secrets.\n\nThe circles in the temple of Cthulhu are actually horocycles. They are infinite, and there is an infinite number of them.";
export const barrierhelp = "Huge, impassable walls which separate various lands.";
export const cavehelp = "This cave contains walls which are somehow living. After each turn, each cell counts the number of living wall and living floor cells around it, and if it is currently of a different type than the majority of cells around it, it switches. Items count as three floor cells, and dead Trolls count as five wall cells. Some foreign monsters also count as floor or wall cells.\n";
export const vinehelp = "The Vineyard is filled with vines. A very dense pattern of straight lines here...\n\nVine Beasts and Vine Spirits change vine cells to grass, and vice versa.";
export const hvinehelp = "A vine is growing here... but only on a half of the cell. How is that even possible?!Most monsters cannot move from this cell to the cell containing the other half. Vine spirits can move only to the adjacent cells which are also adjacent to the other half.";
export const deadcavehelp = "Somehow, this cave has not received the spark of Life yet.";
export const foresthelp = "This forest is quite dry. Beware the bushfires!\nTrees catch fire on the next turn. The temperature of the grass cells rises once per turn for each fire nearby, and becomes fire itself when its temperature has risen 10 times.\nYou can also chop down the trees. Big trees take two turns to chop down.";
export const hivehelp = "The Hive is filled with Hyperbugs. They are huge insects which look a bit like ants, a bit like bees, and a bit like roaches. They live in circular nests, and an army of Hyperbugs will attack any intruder, including you and enemy Hyperbugs. Will you manage to get to the heart of such a nest, and get the precious Royal Jelly?";
export const redrockhelp = "This land contains high rock formations. Most of the valley is at level 0, while items are found at level 3. It is impossible to gain two or more levels, or to lose three levels, in a single move, (attacks are possible at any difference, though). Kill Red Trolls and Rock Snakes to make a cell higher.";
export const caribbeanhelp = "This dangerous sea contains nasty sharks and pirates. ";
export const cislandhelp = "The islands of Caribbean are infinite and circular, and the pirates probably have hidden their treasures somewhere far from the coast.";
export const redsnakedes = "Rock snakes are similar to Sandworms, but they move each turn. However, they only move on the hexagonal cells. They are also somewhat longer than the Sandworms.";
export const minedesc = "This minefield has been created by the Bomberbirds to protect their valuable eggs. Mines explode when they are stepped on, creating fire all around them (this fire never expires in the Minefield). If you don't step on a mine, you know the number of mines in cells around you. These numbers are marked with color codes on the cells you have visited.";
export const palacedesc = "So better just to concentrate on collecting treasure. Beware the traps, and the guards, who are hard to kill!";
export const gatedesc = "Green pressure plates open all gates in radius 3 around them. Similarly, red pressure plates close all gates in this radius.";
export const princessdesc = "A mouse squeaks at you. It seems that it wants you to go somewhere. That's interesting, what could you find here?\n\nNote: in the part of the Palace that you are exploring during this quest, the distribution of monsters, pressure plates, and items has been changed somewhat, to make it a bit more suitable for less experienced players. The number of monsters does not depend on the number of Hypersian Rugs you have collected, and there are more opening plates.\n\nHowever, even with the normal distribution, it appears that it should be always possible to reach your goal. If you want this challenge, select it from the special game modes menu.";
export const elemdesc = "The Elemental Planes are divided into four subzones: Planes of Fire, Water, Air, and Earth. You need to collect a Shard from each Plane to construct an Elemental Gem. It is dangerous to collect too many Shards of the same type without constructing a Gem.";
export const wildwestdesc = "Take a revolver, kill outlaws, collect bounties.\n\nNote: since this land is anachronistic, it is not available in normal game. It is only available in special modes.";
export const elecdesc = "Whenever after your move there is a connection between a charged and a grounded cell, there is a short circuit. All cells on any path connecting a charged and a grounded cell (without repeated cells, or two consecutive grounded/charged cells) become damaged.\n\nSandstone walls and most creatures are conductive. Great Walls are isolators, but lands beyond them count as grounded.\n\nFulgurite, the treasure, is created when you manage to short circuit a sandstone wall, or a Rich Metal Beast.\n\nTrolls leave conductive rocks when killed, and Metal Beasts can only be killed by electricity -- your attacks only stun them, or push them away if already stunned.";
export const overdesc = "The Overgrown Woods are filled with mutant ivies! These plants grow very fast. Each leaf, after being grown, can grow itself on the next turn. However, each part is only able to grow once in 16 turns. Outside of the Overgrown Woods, the Mutant Ivy may grow only on hexagonal cells.\n\nMaybe such fast growing plants could help you solve the problem of hunger in your world? Kill the Mutant Ivies to collect Mutant Saplings.";
export const cleardesc = "A clearing in the Overgrown Woods. Obviously, this gives the Mutant Ivies an infinite space to grow...\n\nMutant Fruits rot if they are not adjacent to a Mutant Ivy.";
export const winddesc = "Someone has put air fans in these plains, causing strong winds everywhere. You think that the purpose is to harness the magical power of Air Elementals, but you are not sure.\n\nAll cells except fans are grouped into three colors according to a pattern. Wind blows counterclockwise around each group of cells of a single color. Cells which are blocked by walls, or at distance at most 2 from an Air Elemental, do not count for this.\n\nIt is illegal to move in a direction which is closer to incoming wind than to outgoing wind. However, you can move two cells with the wind in a single turn, and so can the birds.";
export const warningdesc = "Warnings are issued when you try to do something that appears dangerous, like stepping on a known mine, or getting your boat destroyed by a Kraken without having Orb of the Fish. In some cases the action might actually be safe -- so you can ignore the warning and do it anyway, simply by repeating the action.";
export const hauntdesc = "A dark forest filled with ghosts and graves. But there is also treasure hidden deep within... But don't let greed make you stray from your path, as you can get lost!\n\nThe Haunted Woods are bounded by a single equidistant curve. It is not a circle or horocycle.\n\n";
export const bulldashdesc = "Butterflies don't pursue you -- unless you get next to them, they just spin around the obstacles. They cannot be killed conventionally, but you get treasure when a Raging Bull crashes into a Butterfly. ";
export const prairiedesc = "You can find safety in some places in the Prairie, but if you want treasures, they can be found only on the other side of a giant herd of bulls.";
export const cadesc = "A land for people wanting to experiment with cellular automata in the HyperRogue grid. Rules can be given on the command line; the default rules are:\n-c07 00100000 -c06 0010000 -c17 00011000 -c16 0001100 -caprob 0.3\n(-c0 or -c1 can be given if the same rule is to be used for hexagonal and heptagonal cells).";
export const huntingdesc = "The Happy Hunting Ground is the place where hunting is easy; the spirits of hunters go here after their death, if their life was deemed worthy. You did not qualify though, so you will not ever be able to find your way to the places where the hunter spirits and game are... and their hunting dogs will hunt you instead!\n\nYou hope to use this to learn some skills in fighting in open hyperbolic space, though.";
export const terradesc = "Spending 3-5 turns next to the Terracotta Warriors will cause them to awaken. They have 7 HP, and get stunned for longer and longer time with each attack.";
export const terraldesc = "The Emperor's mausoleum. The army of Terracotta Warriors is supposed to protect him in his afterlife, while the traps are to protect the treasures in the mausoleum from thieves.";
export const arrowtrapdesc = "The arrow traps will automatically launch a deadly arrow when stepped on. They are quite old though, so the arrow will actually fly at the end of the next turn.";
export const lavadesc = "The volcanic activity in this land is extremely unstable. Lava is too hot to walk on. It cools quickly, but another flow will come soon...";
export const blizzarddesc = "Once in the past there lived a tribe whose prophets warned about the great blizzard that was to come and freeze the world. They thought it was the wrath of the gods, so they put some altars, so that the gods could hear their pleas. The mighty golems guarded those altars, making sure nobody steals the jewels, because a robbed god is a angry god. Unfortunately winter has come (maybe because only the monks knew how to stop the golems, and they were said to had escaped earlier with some of the jewels). The tribe has frozen to death, altars got covered with snow and ice. Only ice golems still guard them waiting for the spring.";
export const crystaldesc = "Yes, this is definitely a crystal. A very regular crystalline structure.\n\nThis land has been designed as a tool to play with various geometries, and it does not appear during a normal gameplay.";
export const NODESC = "No description yet.";
export const NODESCYET = "No description yet.";
export const GENDERSWITCH = NODESC;
export const warplanddesc = "This land is warped. Ironically, the coast is completely straight...";
export const roselanddesc = "This land is filled with beautiful, but dangerous, creatures and plants.";
export const dragondesc = "Dragons are powerful monsters. They are slow, but evil, and love to pick on creatures who are even slower than them. They must be stopped!\n\nA Dragon moves each two turns. It may attack with all its segments, or move its whole body forwards or backwards, it may also move a frontal part backwards. To kill a Dragon, you need to hit each of its segments. The head will regenerate on the turns the Dragon is not moving, so you will usually have to hit it with your last attack; otherwise, if the head is healthy, it may breathe fire (at range 3), losing the hitpoint. Killing the Dragon while still in the Dragon Chasms gives you treasure.";
export const tortoisedesc = "Galápagos is the land of Tortoises. They are very slow, which allows the Dragons to pick on them by stealing and eating their young. Bring the Baby Tortoises back, but, there is a catch: the Tortoises come in many varieties, depending on the part of Galápagos they live in -- there are 21 binary environmental factors, and thus 2097152 varieties. You'll have to find a Tortoise which matches the baby exactly!\n\nTortoises move each 3 turns, and attacks only stun them.\n\nBringing back a Baby Tortoise counts as 5 $$$. The more factors agree in the given location of Galápagos, the brighter it is shown on your screen.";
export const krakendesc = "There are Krakens in your homeland, too... huge sea monsters which could easily destroy ships. The geometry of this strange world prevents quick movement of huge objects, so there are no large ships, only small boats, and hyperbolic Krakens are relatively small too. Still, you suppose they might be the widest creatures which could still move at considerable speed...\n\nKraken heads can move only on hexagons. You need to attack all the tentacles to kill the Kraken. A tentacle cannot attack if it has been attacked on the same turn. When a Kraken attacks you while you are in a boat, it destroys the boat, but does not kill you.";
export const halloweendesc = "Halloween is a special land, that is available only in the spherical or elliptic geometry (press 'o' to switch). You play on the surface of a jack-o'-lantern, and have to collect as many Treats as possible. Each Treat you collect brings new monsters to fight, and new magical powers for you. You have to fight the monsters while effectively managing your limited resources.";
export const reptiledesc = "These reptiles are quite strange creatures. They spend most of their lives sleeping as floors that other creatures can walk on. Sometimes they wake up to hunt their prey, but they will happily go back to sleep if they happen to move into a hole on their way. Your attacks do not kill the Reptiles, but you can push and stun them.";
export const naturedesc = "This Orb allows you to grow like an Ivy. The Ivy is always rooted in your current location; moving among the Ivy cells will move the root. Moving to a new location will cause the Ivy to grow , if an Ivy could make that movement (otherwise it breaks). You can also target one of the cells adjacent to your ivy (not to you) to grow or attack there.";
export const mirroreddesc = "A perfect mirror wall. It is unbreakable and impassable even for aethereal beings, and everything you see inside is just an image of the real world; you can swing your sword at them, but that will not destroy them in the real world. Mirror walls reflect Mimics, lightning bolts, and missiles perfectly.";
export const tamebomberdesc = "This bomberbird will follow you at some distance, and attack your enemies. You can kill it to place a mine.";
export const gargdesc = "A being made of stone, who likes high buildings. It becomes normal stone when killed, but only if next to something stable -- otherwise it falls.";
export const lakeDesc = "Hell has these lakes everywhere... They are shaped like evil stars, and filled with burning sulphur.";
export const thumpdesc = "A device that attracts sandworms and other enemies. You need to activate it.";
export const twdesc = "This structure will disappear after some time.";
export const jellydesc = "Some of the Slime Beasts have decided to revolt against the color rules in the Alchemist Lab. They have changed their shape and consistency, declared independence, and established their own Kingdom.\n\nJellies switch between being a wall and being a monster after every treasure you collect.";
export const ruindesc = "Once a beautiful city... but now overrun by the mighty Raiders of unknown origin.\n\nRaiders cannot be harmed with mundane weapons, but each color has its movement restrictions.";
export const rock_description = "Shoot the Space Rocks for score. Large Rocks will split into two smaller rocks.";

export interface monstertype { glyph: number; color: number; name: string; flags: flagtype; mgroup: eMonster; help: string; }
